fn is_min_heap(a: &Vec<i32>) -> bool {
    let n = a.len();
    // Only need to check all parents from 0 up to floor(n/2) - 1
    // because nodes beyond that are leaves with no children.
    for i in 0..(n / 2) {
        let left = 2 * i + 1;
        if left < n && a[i] > a[left] {
            return false;
        }
        let right = 2 * i + 2;
        if right < n && a[i] > a[right] {
            return false;
        }
    }
    true
}